using UnityEngine;
using UnityEditor;
using System;
using System.IO;
using ConRoi.Investigation.V36;
using Object = UnityEngine.Object;

namespace Unity.AI.Assistant.Agent.Dynamic.Extension.Editor
{
    internal class CommandScript : IRunCommand
    {
        public void Execute(ExecutionResult r)
        {
            var s = Object.FindFirstObjectByType<InvestigationSession>();
            var w = EditorWindow.GetWindow(Type.GetType("UnityEditor.GameView,UnityEditor"));
            r.Log("window=" + w.position + " screen=" + Screen.width + "/" + Screen.height);
            var p = new Vector2(160, 274);
            w.SendEvent(new Event{type = EventType.MouseDown, button = 0, mousePosition = p});
            w.SendEvent(new Event{type = EventType.MouseUp, button = 0, mousePosition = p});
            double until = EditorApplication.timeSinceStartup + .7;
            EditorApplication.CallbackFunction done = null;
            done = () =>
            {
                if (EditorApplication.timeSinceStartup < until)
                    return;
                EditorApplication.update -= done;
                File.WriteAllText("Test/KetQua/investigation_r102/ui-click-probe.txt", "EditorWindow synthetic mouse page=" + s.Page + " Screen=" + Screen.width + "x" + Screen.height + " window=" + w.position);
                ScreenCapture.CaptureScreenshot("Test/BangChung/investigation_r102/cipher-ui-click.png");
            };
            EditorApplication.update += done;
            r.Log("Sent mouse click to Game view; result after actual frames");
        }
    }
}

